-- ARANDÚ — precios finales para revisión
-- Promociones excluidas.
-- No modifica tablas canónicas; crea únicamente tablas de staging.
-- No se contactó a establecimientos ni personas.

BEGIN;
CREATE SCHEMA IF NOT EXISTS staging_arandu;

CREATE TABLE IF NOT EXISTS staging_arandu.facility_prices_ready_20260814 (
  arandu_id text PRIMARY KEY,
  facility_name text NOT NULL,
  department text, locality text, address text,
  price_status text NOT NULL, price_status_label text NOT NULL,
  price_kind text NOT NULL, modalities text,
  original_currency text NOT NULL,
  original_price_min numeric, original_price_max numeric,
  exchange_rate_to_uyu numeric, conversion_date date,
  normalization_method text,
  normalized_price_min_uyu integer, normalized_price_max_uyu integer,
  display_price_uyu text, source_date_text text, source_year_latest integer,
  source_label text, source_url text,
  price_confidence text, price_confidence_label text,
  match_confidence text, include_in_main_price_filter boolean NOT NULL,
  display_mode text NOT NULL, review_status text NOT NULL DEFAULT 'pending',
  record_ids text, notes text, warning text,
  CHECK (review_status IN ('pending','approved','rejected','needs_research'))
);


CREATE TABLE IF NOT EXISTS staging_arandu.facility_price_evidence_20260814 (
  record_id text PRIMARY KEY, arandu_id text, facility_name text NOT NULL,
  department text, locality text, address text, matched_to_arandu boolean NOT NULL,
  evidence_type text, evidence_category text, modality text,
  original_currency text, original_price_min numeric, original_price_max numeric,
  exchange_rate_to_uyu numeric, normalized_price_min_uyu integer,
  normalized_price_max_uyu integer, source_date_text text, source_year integer,
  source_label text, source_url text, raw_text text, includes text,
  temporal_status text, price_confidence text, match_confidence text,
  publish_recommendation text, notes text, review_status text NOT NULL DEFAULT 'pending',
  CHECK (review_status IN ('pending','approved','rejected','needs_research'))
);


COMMIT;

